import { validateEvent } from '../datalayer.js';

// Coding Arena challenge catalogue. Add an object to extend it; the Arena, dashboard skill radar and lessons pick it up.
//
// Challenge schema
//   id        unique, kebab-case. Saved in the existing 'katas' storage array when solved (XP key 'kata:<id>').
//   cat       one of CATEGORIES ids
//   level     'beginner' | 'intermediate' | 'advanced'
//   xp        reward (beginner 50, intermediate 75, advanced 100; the three original katas keep 75)
//   title, desc (html), starter (code string), hints [string, ...] (revealed one by one), success (BIT-style message)
//   mode      'fn'    -> define function `fn`; `tests` run through sandbox.runTests: [{args, expect, name?} | {expr, name?}]
//             'dom'   -> `html` (page markup) + `checks` [{name, expr}] run through sandbox.runDomChecks
//             'dl'    -> code pushes to window.dataLayer; `verify(pushes, info) -> [{name, pass, note?}]` is run on the captured pushes
//                        (info = {reassigned, error}). Optional `html` + `act` (a JS expression run after the code, e.g. clicking a button).
//             'out'   -> `expect` is an array of exact console lines the code must print (use sparingly)
//   debug     optional true: shown in the Debugging category with a "fix the bug" banner
//   solution  reference solution (string). Shown after solving or on request; verified by the arena test harness.
export const CATEGORIES = [
  ['variables', 'Variables', 'cube', 'mint'], ['datatypes', 'Data Types', 'layers', 'aqua'], ['arrays', 'Arrays', 'list', 'mint'],
  ['objects', 'Objects', 'braces', 'violet'], ['conditions', 'Conditions', 'branch', 'js'], ['functions', 'Functions', 'func', 'violet'],
  ['dom', 'DOM', 'tree', 'aqua'], ['events', 'Events', 'pointer', 'js'], ['json', 'JSON', 'database', 'violet'],
  ['tracking', 'Tracking', 'radar', 'mint'], ['debugging', 'Debugging', 'bug', 'coral']
];
export const LEVELS = { beginner: { label: 'Beginner', xp: 50, color: 'mint' }, intermediate: { label: 'Intermediate', xp: 75, color: 'js' }, advanced: { label: 'Advanced', xp: 100, color: 'coral' } };

const R = (name, pass, note) => ({ name, pass: !!pass, note });
const only = (pushes, ev) => pushes.filter(p => p && p.event === ev);
const noErr = (p, v) => { const bad = validateEvent(p, v || { cleared: true, seenTx: new Set() }).filter(i => i.level === 'error'); return { pass: !bad.length, note: bad.map(b => b.msg).join('; ') }; };

