    starter: 'const fetchUser = (id) => new Promise((resolve) => setTimeout(() => resolve({ id, name: "User " + id }), 20));\n\nasync function loadName(id) {\n  const user = fetchUser(id);\n  return user.name;\n}\n\nloadName(1).then(console.log);',
    hints: ['Log user inside loadName. What do you actually get?', 'Without await, user is still a pending Promise, and a Promise has no name property.', 'const user = await fetchUser(id);'],
